        fpr[gruppe] = round(z["fp"] / (z["fp"] + z["tn"]), 3)
        selrate[gruppe] = round((z["tp"] + z["fp"]) / (z["tp"] + z["fp"] + z["fn"] + z["tn"]), 3)
